// AI generated by pi coding agent, v1.0
// ---------------------------------------------------------------------------
// Application bootstrap: builds the panels, wires the preset buttons and keeps
// everything in sync with the API.
// ---------------------------------------------------------------------------

import './style.css';

import { ApiError, fetchCurrent, fetchSeries, fetchStats, fetchYears } from './api';
import { seriesColor, TimeSeriesChart } from './chart';
import { defaultPreset, PRESETS, presetForId, resolveRange, yearPreset } from './presets';
import { ThemeController } from './theme';
import type {
  CurrentResponse,
  Field,
  Preset,
  SeriesResponse,
  StatsResponse,
  ThemeMode,
  YearInfo,
} from './types';
import { FIELDS, fieldMeta } from './types';

const PRESET_KEY = 'pi-sensor-preset';
const COLLAPSED_KEY = 'pi-sensor-collapsed';
const REFRESH_MS = 60_000;
const STATS_HOURS = 24;

// ---------------------------------------------------------------------------
// DOM helpers
// ---------------------------------------------------------------------------

function byId<T extends HTMLElement>(id: string): T {
  const node = document.getElementById(id);
  if (!node) throw new Error(`missing element #${id}`);
  return node as T;
}

function element<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  className?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

// ---------------------------------------------------------------------------
// Formatting
// ---------------------------------------------------------------------------

/** Format a measurement with a German decimal comma. */
function formatValue(value: number | null | undefined, decimals: number): string {
  if (value === null || value === undefined || Number.isNaN(value)) return '–';
  return value.toFixed(decimals).replace('.', ',');
}

/** Parse a MySQL DATETIME ("YYYY-MM-DD HH:MM:SS", Pi-local) into a Date. */
function parseLocal(value: string): Date | null {
  const date = new Date(value.replace(' ', 'T'));
  return Number.isNaN(date.getTime()) ? null : date;
}

const dateTimeFormat = new Intl.DateTimeFormat('de-AT', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});

function formatDateTime(value: string | null): string {
  if (!value) return 'keine Daten';
  const date = parseLocal(value);
  return date ? `${dateTimeFormat.format(date)} Uhr` : value;
}

/** Format a unix timestamp (seconds) in the browser's local time zone. */
function formatEpoch(seconds: number): string {
  return dateTimeFormat.format(new Date(seconds * 1000));
}

// ---------------------------------------------------------------------------
// Cards: current values
// ---------------------------------------------------------------------------

function renderCurrent(host: HTMLElement, timeHost: HTMLElement, data: CurrentResponse, dark: boolean): void {
  host.replaceChildren();

  for (const meta of FIELDS) {
    const card = element('div', 'card');

    const label = element('div', 'card-label');
    const dot = element('span', 'card-dot');
    dot.style.background = seriesColor(meta.key, dark);
    label.append(dot, document.createTextNode(meta.label));

    const value = element('div', 'card-value');
    value.append(
      document.createTextNode(formatValue(data[meta.key], meta.decimals)),
      element('span', 'card-unit', meta.unit),
    );

    card.append(label, value);
    host.append(card);
  }

  timeHost.textContent = formatDateTime(data.measured_at);
}

// ---------------------------------------------------------------------------
// Table: 24 h min / avg / max
// ---------------------------------------------------------------------------

function renderStats(host: HTMLElement, data: StatsResponse, dark: boolean): void {
  host.replaceChildren();

  for (const meta of FIELDS) {
    const stats = data.stats[meta.key];
    const block = element('div', 'stat');

    const label = element('div', 'stat-label');
    const dot = element('span', 'card-dot');
    dot.style.background = seriesColor(meta.key, dark);
    label.append(dot, document.createTextNode(meta.label));
    block.append(label);

    const rows: Array<[string, number | null, string]> = [
      ['Minimum', stats?.min ?? null, 'min'],
      ['Durchschnitt', stats?.avg ?? null, ''],
      ['Maximum', stats?.max ?? null, 'max'],
    ];

    for (const [name, value, modifier] of rows) {
      const row = element('div', 'stat-row');
      row.append(
        element('span', 'stat-key', name),
        element('span', `stat-value ${modifier}`.trim(), `${formatValue(value, meta.decimals)} ${meta.unit}`),
      );
      block.append(row);
    }

    host.append(block);
  }
}

// ---------------------------------------------------------------------------
// Chart panel: legend + presets
// ---------------------------------------------------------------------------

function renderLegendItems(host: HTMLElement, fields: readonly Field[], dark: boolean): void {
  host.replaceChildren();

  for (const field of fields) {
    const meta = fieldMeta(field);
    const item = element('span', 'legend-item');
    const swatch = element('span', `legend-swatch${meta.axis === 'hum' ? ' dashed' : ''}`);
    if (meta.axis === 'hum') {
      // The dashed swatch draws its dashes with a currentColor gradient, so only
      // `color` may be set - the `background` shorthand would replace the image.
      swatch.style.color = seriesColor(field, dark);
    } else {
      swatch.style.background = seriesColor(field, dark);
    }
    item.append(swatch, document.createTextNode(meta.label));
    host.append(item);
  }
}

function renderPresetButtons(host: HTMLElement, active: Preset, onSelect: (preset: Preset) => void): void {
  host.replaceChildren();

  for (const preset of PRESETS) {
    const button = element('button', 'preset', preset.label);
    button.type = 'button';
    button.setAttribute('aria-pressed', preset.id === active.id ? 'true' : 'false');
    button.addEventListener('click', () => onSelect(preset));
    host.append(button);
  }
}

const YEAR_PLACEHOLDER = 'Vergangenes Jahr …';

/**
 * Fill the "past years" dropdown.
 *
 * The current year has its own preset button, so it is left out here. When there
 * is no past year at all the select is hidden instead of showing an empty menu.
 */
function renderYearOptions(
  select: HTMLSelectElement,
  years: readonly YearInfo[],
  currentYear: number,
  active: Preset,
): void {
  const pastYears = years.filter((info) => info.year < currentYear).sort((a, b) => b.year - a.year);

  select.replaceChildren();

  if (pastYears.length === 0) {
    select.hidden = true;
    return;
  }

  select.hidden = false;

  const placeholder = element('option', undefined, YEAR_PLACEHOLDER);
  placeholder.value = '';
  select.append(placeholder);

  for (const info of pastYears) {
    const option = element('option', undefined, String(info.year));
    option.value = String(info.year);
    select.append(option);
  }

  select.value = active.range.kind === 'year' ? String(active.range.year) : '';
}

// ---------------------------------------------------------------------------
// Stored preset choice
// ---------------------------------------------------------------------------

function loadPreset(): Preset {
  try {
    const stored = presetForId(localStorage.getItem(PRESET_KEY));
    if (stored) return stored;
  } catch {
    // Storage unavailable: fall back to the default preset.
  }
  return defaultPreset();
}

function storePreset(id: string): void {
  try {
    localStorage.setItem(PRESET_KEY, id);
  } catch {
    // Best effort only.
  }
}

// ---------------------------------------------------------------------------
// Collapsible panels
// ---------------------------------------------------------------------------

/** Ids of the panels that are currently folded away. */
function loadCollapsed(): Set<string> {
  try {
    const raw = localStorage.getItem(COLLAPSED_KEY);
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        return new Set(parsed.filter((value): value is string => typeof value === 'string'));
      }
    }
  } catch {
    // Corrupt or unavailable storage: start expanded.
  }
  return new Set();
}

function storeCollapsed(collapsed: ReadonlySet<string>): void {
  try {
    localStorage.setItem(COLLAPSED_KEY, JSON.stringify([...collapsed]));
  } catch {
    // Best effort only.
  }
}

/** One panel that can be folded away via the chevron in its head. */
interface CollapsiblePanel {
  /** Key used in localStorage. */
  key: string;
  panel: HTMLElement;
  button: HTMLButtonElement;
  /** Human readable name for the tooltip. */
  label: string;
}

// ---------------------------------------------------------------------------
// Dashboard
// ---------------------------------------------------------------------------

class Dashboard {
  private readonly theme = new ThemeController();
  private readonly chart: TimeSeriesChart;
  private preset: Preset = loadPreset();
  private timer: number | null = null;
  private busy = false;
  /** Years that hold data, as reported by api/years.php. */
  private years: readonly YearInfo[] = [];
  /** Current calendar year according to the database clock. */
  private currentYear = new Date().getFullYear();
  /** Panels the user folded away (persisted). */
  private readonly collapsed = loadCollapsed();

  private readonly ui = {
    status: byId<HTMLSpanElement>('status'),
    error: byId<HTMLParagraphElement>('error'),
    btnRefresh: byId<HTMLButtonElement>('btn-refresh'),
    btnTheme: byId<HTMLButtonElement>('btn-theme'),
    currentTime: byId<HTMLSpanElement>('current-time'),
    cards: byId<HTMLDivElement>('cards-current'),
    stats: byId<HTMLDivElement>('stats-24h'),
    legend: byId<HTMLDivElement>('chart-legend'),
    presets: byId<HTMLDivElement>('presets'),
    yearSelect: byId<HTMLSelectElement>('year-select'),
    chartHost: byId<HTMLDivElement>('chart'),
    footer: byId<HTMLSpanElement>('footer-meta'),
  };

  constructor() {
    this.chart = new TimeSeriesChart(this.ui.chartHost);

    this.theme.onChange((dark) => {
      this.chart.setTheme(dark);
      this.applyThemeUi(dark);
    });
    this.theme.apply();

    this.ui.btnTheme.addEventListener('click', () => {
      this.theme.cycle();
    });

    this.ui.btnRefresh.addEventListener('click', () => {
      void this.reload();
    });

    this.setupCollapsible([
      {
        key: 'current',
        panel: byId<HTMLElement>('panel-current'),
        button: byId<HTMLButtonElement>('btn-collapse-current'),
        label: 'Aktuelle Werte',
      },
      {
        key: 'stats',
        panel: byId<HTMLElement>('panel-stats'),
        button: byId<HTMLButtonElement>('btn-collapse-stats'),
        label: 'Letzte 24 Stunden',
      },
    ]);

    this.ui.yearSelect.addEventListener('change', () => {
      const value = this.ui.yearSelect.value;
      if (value === '') {
        // Placeholder picked: restore the selection instead of switching.
        this.renderYears();
        return;
      }
      this.selectPreset(yearPreset(Number(value)));
    });

    // A hidden tab does not need to poll the API.
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') void this.reload();
    });
  }

  async start(): Promise<void> {
    this.renderPresets();
    await this.loadYears();
    await this.reload();
    this.timer = window.setInterval(() => {
      if (document.visibilityState === 'visible') void this.reload();
    }, REFRESH_MS);
  }

  stop(): void {
    if (this.timer !== null) window.clearInterval(this.timer);
    this.timer = null;
    this.chart.destroy();
  }

  // -- collapsible panels ---------------------------------------------------

  /**
   * Wire the collapse toggles. The chart panel has no toggle of its own: it is
   * the flex child that absorbs whatever height the folded panels release, so
   * the chart grows automatically (its ResizeObserver redraws it).
   */
  private setupCollapsible(panels: readonly CollapsiblePanel[]): void {
    const apply = (panel: CollapsiblePanel): void => {
      const collapsed = this.collapsed.has(panel.key);
      panel.panel.dataset.collapsed = collapsed ? 'true' : 'false';
      panel.button.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
      panel.button.title = collapsed ? `${panel.label} ausklappen` : `${panel.label} einklappen`;
    };

    for (const panel of panels) {
      apply(panel);
      panel.button.addEventListener('click', () => {
        if (this.collapsed.has(panel.key)) {
          this.collapsed.delete(panel.key);
        } else {
          this.collapsed.add(panel.key);
        }
        apply(panel);
        storeCollapsed(this.collapsed);
      });
    }
  }

  // -- rendering ------------------------------------------------------------

  private renderPresets(): void {
    renderPresetButtons(this.ui.presets, this.preset, (preset) => this.selectPreset(preset));
    this.renderYears();
    this.renderLegend();
  }

  private renderYears(): void {
    renderYearOptions(this.ui.yearSelect, this.years, this.currentYear, this.preset);
  }

  /** Switch to another preset (or just reset the zoom when it is the same one). */
  private selectPreset(preset: Preset): void {
    if (preset.id === this.preset.id) {
      this.chart.resetZoom();
      return;
    }

    this.preset = preset;
    storePreset(preset.id);
    this.renderPresets();
    void this.loadSeries(false).catch((error: unknown) => this.showError(error));
  }

  /**
   * Read which years exist. Not fatal: without the list the dropdown simply
   * stays hidden and "Aktuelles Jahr" falls back to the browser's year.
   */
  private async loadYears(): Promise<void> {
    try {
      const response = await fetchYears();
      this.currentYear = response.current_year;
      this.years = response.years;
    } catch {
      this.years = [];
    }

    // A stored year preset that no longer holds data falls back to the default.
    if (this.preset.range.kind === 'year' && !this.years.some((info) => info.year === (this.preset.range as { year: number }).year)) {
      if (this.years.length > 0) {
        this.preset = defaultPreset();
        storePreset(this.preset.id);
      }
    }

    this.renderPresets();
  }

  private renderLegend(): void {
    renderLegendItems(this.ui.legend, this.preset.fields, this.theme.isDark());
  }

  private applyThemeUi(dark: boolean): void {
    const mode = this.theme.getMode();
    const icon: Record<ThemeMode, string> = { light: '☀', dark: '☾', auto: '◐' };
    const label: Record<ThemeMode, string> = {
      light: 'Design: hell',
      dark: 'Design: dunkel',
      auto: 'Design: automatisch',
    };
    this.ui.btnTheme.textContent = icon[mode];
    this.ui.btnTheme.title = `${label[mode]} (klicken zum Wechseln)`;
    this.renderLegend();
    // Re-render the cards and the statistics so their dots follow the theme.
    if (this.lastCurrent) renderCurrent(this.ui.cards, this.ui.currentTime, this.lastCurrent, dark);
    if (this.lastStats) renderStats(this.ui.stats, this.lastStats, dark);
  }

  // -- data loading ---------------------------------------------------------

  private lastCurrent: CurrentResponse | null = null;
  private lastStats: StatsResponse | null = null;

  private async reload(): Promise<void> {
    if (this.busy) return;
    this.busy = true;
    this.ui.status.textContent = 'lade …';

    try {
      const [current, stats] = await Promise.all([
        fetchCurrent(),
        fetchStats(STATS_HOURS),
      ]);

      this.lastCurrent = current;
      this.lastStats = stats;

      renderCurrent(this.ui.cards, this.ui.currentTime, current, this.theme.isDark());
      renderStats(this.ui.stats, stats, this.theme.isDark());

      // Same preset as before: a zoom the user made must survive the refresh.
      await this.loadSeries(true);

      this.ui.status.textContent = `Stand ${new Date().toLocaleTimeString('de-AT', {
        hour: '2-digit',
        minute: '2-digit',
      })}`;
      this.hideError();
    } catch (error) {
      this.showError(error);
      this.ui.status.textContent = '';
    } finally {
      this.busy = false;
    }
  }

  private async loadSeries(keepZoom: boolean): Promise<void> {
    const window = resolveRange(this.preset.range, this.currentYear);
    const response = await fetchSeries({
      ...window,
      fields: this.preset.fields,
      bucket: this.preset.bucket,
    });
    this.applySeries(response, keepZoom);
  }

  private applySeries(response: SeriesResponse, keepZoom: boolean): void {
    this.chart.setData(response.points, response.fields, response.bucket, keepZoom);

    const first = response.points[0];
    const last = response.points[response.points.length - 1];
    const range = first && last ? `${formatEpoch(first.t)} – ${formatEpoch(last.t)}` : 'keine Daten';

    this.ui.footer.textContent = `${this.preset.label} · ${response.points.length} Punkte · Auflösung ${bucketLabel(
      response.bucket,
    )} · ${range}`;
  }

  private showError(error: unknown): void {
    const message = error instanceof ApiError ? error.message : (error as Error).message;
    this.ui.error.textContent = `Daten konnten nicht geladen werden: ${message}`;
    this.ui.error.hidden = false;
  }

  private hideError(): void {
    this.ui.error.hidden = true;
    this.ui.error.textContent = '';
  }
}

function bucketLabel(bucket: SeriesResponse['bucket']): string {
  switch (bucket) {
    case '5m':
      return '5 Minuten';
    case '1h':
      return '1 Stunde';
    case '1d':
      return '1 Tag';
  }
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

const dashboard = new Dashboard();
void dashboard.start();
// End of AI generated by pi coding agent, v1.0
